def solve(n, a, b):
    a_str = str(a)
    b_str = str(b)

    # Check if transformation is possible
    if any(a_str[i] > b_str[i] for i in range(n)) or any(a_str[i] < b_str[i] for i in range(n)):
        return -1

    # Initialize the queue for BFS
    queue = deque([(a_str, [])])
    visited = set([a_str])

    while queue:
        current_num, path = queue.popleft()

